using System;using UnityEngine;using FakeFantasyOnline.Presentation.ReferenceAssets;
class PointerSafetyContract {
 static int checks;static bool sampleFirst;static void Check(bool c,string m){checks++;if(!c)throw new Exception(m);}
 static Touch T(int id,TouchPhase p,Vector2 gui)=>new Touch{fingerId=id,phase=p,position=new Vector2(gui.x,Screen.height-gui.y)};
 static Touch Fixed(int id,int a,TouchPhase p)=>T(id,p,MobileClientPresentation.FixedActionRect((MobileFixedAction)a).center);
 static Touch Stick(TouchPhase p)=>T(2,p,new Vector2(180,900));static Touch Skill(TouchPhase p)=>T(3,p,new Vector2(720,825));
 static void Frame(float dt,params Touch[] t){Time.frameCount++;Time.unscaledTime+=dt;Input.touches=t;if(sampleFirst)ClientInput.Refresh();GameHud.I.Tick();ClientInput.Refresh();}
 static void Reset(){MobileClientPresentation.LayoutEditing=false;MobileClientPresentation.MenuExpanded=false;MobileClientPresentation.ClosedFrame=-100;MobileClientPresentation.LayoutPanelsOpen=MobileClientPresentation.ModalOpen=MobileClientPresentation.PanelPointer=MobileClientPresentation.DiagramOpen=false;MobileClientPresentation.SaveFails=false;MobileClientPresentation.Edits.Clear();MobileClientPresentation.SafeAreaGui=new Rect(0,0,1000,1000);ClientInput.CancelAll();GameHud.I=new GameHud();GameHud.FixedUses=new int[4];PlayerController.I=new PlayerController();NetClient.I=new NetClient();GameHud.hotSkill[0]=1;SkillTargeting.Mode=SkillTargeting.Aim.Single;CombatWorld.I.monsters.Clear();CombatWorld.I.monsters[1]=new MonsterEntity{id=1,worldX=50,worldY=0};TargetSelect.CurrentSourceForIndependentRuntime=CombatWorld.I.monsters[1];Frame(.01f);}
 static void Unlock(int a=0){Frame(.01f,Fixed(1,a,TouchPhase.Began));Frame(.66f,Fixed(1,a,TouchPhase.Stationary));Check(MobileClientPresentation.LayoutEditing,"hold unlocks "+a);Frame(.01f,Fixed(1,a,TouchPhase.Ended));Frame(.01f);Check(!GameHud.I.EditAwaitRelease,"entry finger must release");}
 static void Tap(Vector2 p){Frame(.01f,T(7,TouchPhase.Began,p));Frame(.01f,T(7,TouchPhase.Ended,p));}
 static void Main(){
 foreach(bool before in new[]{true,false}){sampleFirst=before;
 for(int a=0;a<4;a++){Reset();Frame(.01f,Stick(TouchPhase.Began),Fixed(1,a,TouchPhase.Began),Skill(TouchPhase.Began));Check(ClientInput.JoystickHeld&&SkillTargeting.MobileHotSlotActive,"three independent owners");Frame(.1f,Stick(TouchPhase.Stationary),Fixed(1,a,TouchPhase.Ended),Skill(TouchPhase.Stationary));Check(GameHud.FixedUses[a]==1&&!MobileClientPresentation.LayoutEditing&&ClientInput.JoystickHeld&&SkillTargeting.MobileHotSlotActive,"short fixed tap preserves stick+skill "+a);Frame(.01f,Stick(TouchPhase.Stationary),Skill(TouchPhase.Ended));Check(NetClient.I.Uses==1&&ClientInput.JoystickHeld,"skill still casts independently");}
 for(int a=0;a<3;a++){Reset();Frame(.01f,Stick(TouchPhase.Began),Fixed(1,a,TouchPhase.Began),Skill(TouchPhase.Began));Frame(.66f,Fixed(1,a,TouchPhase.Stationary),Skill(TouchPhase.Stationary),Stick(TouchPhase.Stationary));Check(MobileClientPresentation.LayoutEditing&&GameHud.FixedUses[a]==0&&!ClientInput.JoystickHeld&&!SkillTargeting.MobileHotSlotActive&&PlayerController.I.LayoutStops==1,"hold atomically cancels active actions "+a);Frame(.1f,Fixed(1,a,TouchPhase.Ended),Skill(TouchPhase.Ended),Stick(TouchPhase.Ended));Check(GameHud.FixedUses[a]==0&&NetClient.I.Uses==0&&!ClientInput.Pointer.Down&&!ClientInput.Pointer.Up,"entry releases never dispatch");}
 foreach(bool reversed in new[]{true,false})foreach(bool holdEnds in new[]{true,false}){Reset();Frame(.01f,Fixed(1,0,TouchPhase.Began),Skill(TouchPhase.Began));Touch h=Fixed(1,0,holdEnds?TouchPhase.Ended:TouchPhase.Stationary),k=Skill(TouchPhase.Ended);if(reversed)Frame(.66f,k,h);else Frame(.66f,h,k);Check(MobileClientPresentation.LayoutEditing&&NetClient.I.Uses==0&&GameHud.FixedUses[0]==0,"hold threshold preempts same-frame skill release in either touch order");}
 Reset();Frame(.01f,Fixed(1,3,TouchPhase.Began));Frame(.7f,Fixed(1,3,TouchPhase.Stationary));Frame(.01f,Fixed(1,3,TouchPhase.Ended));Check(!MobileClientPresentation.LayoutEditing&&GameHud.FixedUses[3]==0,"sit hold never opens editor or sends release action");
 foreach(string interruption in new[]{"cancel","outside","slop","missing","panel","menu","modal","focus","pause","hide","resize"}){Reset();Frame(.01f,Fixed(1,1,TouchPhase.Began));var p=MobileClientPresentation.HealthPotionRect.center;
  if(interruption=="cancel")Frame(.1f,Fixed(1,1,TouchPhase.Canceled));else if(interruption=="outside")Frame(.1f,T(1,TouchPhase.Moved,p+new Vector2(90,0)));else if(interruption=="slop")Frame(.1f,T(1,TouchPhase.Moved,p+new Vector2(15,0)));else if(interruption=="missing")Frame(.1f);else{if(interruption=="panel")MobileClientPresentation.PanelPointer=true;if(interruption=="menu")MobileClientPresentation.MenuExpanded=true;if(interruption=="modal")MobileClientPresentation.ModalOpen=true;if(interruption=="focus")GameHud.I.LoseFocus();if(interruption=="pause")GameHud.I.Pause();if(interruption=="hide")GameHud.I.showHotbar=false;if(interruption=="resize")MobileClientPresentation.SafeAreaGui=new Rect(0,0,900,1000);Frame(.1f,Fixed(1,1,TouchPhase.Stationary));}
  MobileClientPresentation.PanelPointer=MobileClientPresentation.ModalOpen=MobileClientPresentation.MenuExpanded=false;GameHud.I.showHotbar=true;Frame(.6f,Fixed(1,1,TouchPhase.Ended));Check(GameHud.FixedUses[1]==0&&!MobileClientPresentation.LayoutEditing,"cancelled fixed stays inert "+interruption);
 }
 Reset();Frame(.01f,Fixed(1,0,TouchPhase.Began));Frame(.01f,Fixed(2,0,TouchPhase.Began),Fixed(1,0,TouchPhase.Stationary));Frame(.01f,Fixed(2,0,TouchPhase.Ended),Fixed(1,0,TouchPhase.Stationary));Check(GameHud.FixedUses[0]==0,"second finger cannot steal fixed control");Frame(.01f,Fixed(1,0,TouchPhase.Ended));Check(GameHud.FixedUses[0]==1,"original fixed owner releases once");
 Reset();MobileClientPresentation.LayoutPanelsOpen=true;Frame(.01f,Fixed(1,0,TouchPhase.Began));Frame(.7f,Fixed(1,0,TouchPhase.Stationary));Frame(.01f,Fixed(1,0,TouchPhase.Ended));Check(!MobileClientPresentation.LayoutEditing&&GameHud.FixedUses[0]==0,"open panel rejects edit without turning hold into tap");
 Reset();Unlock();var joy=MobileClientPresentation.ResolveControlRect(MobileControlId.Joystick);Frame(.01f,T(7,TouchPhase.Began,joy.center));Frame(.01f,T(7,TouchPhase.Moved,joy.center+new Vector2(150,-60)));Check(!ClientInput.JoystickHeld&&MobileClientPresentation.Edits.Count==1,"drag edits only");Frame(.01f,T(7,TouchPhase.Ended,joy.center+new Vector2(150,-60)));Check(GameHud.FixedUses[0]==0&&NetClient.I.Uses==0,"editor drag never sends action");Tap(GameHud.I.EditButton(2).center);Check(MobileClientPresentation.LayoutEditing&&MobileClientPresentation.Edits.Count==0,"reset stays edit");Frame(.01f);MobileClientPresentation.SaveFails=true;Tap(GameHud.I.EditButton(0).center);Check(MobileClientPresentation.LayoutEditing,"save failure stays editable");MobileClientPresentation.SaveFails=false;Tap(GameHud.I.EditButton(0).center);Check(!MobileClientPresentation.LayoutEditing&&MobileClientPresentation.GameplayInputBlocked&&!ClientInput.Pointer.Up,"save exits with release shield");Frame(.01f);Check(!MobileClientPresentation.GameplayInputBlocked,"next fresh frame unlocked");
 Reset();Unlock();MobileClientPresentation.LayoutPanelsOpen=true;Frame(.01f,T(7,TouchPhase.Began,new Vector2(500,500)));Check(!MobileClientPresentation.LayoutEditing&&MobileClientPresentation.GameplayInputBlocked&&NetClient.I.Uses==0,"incoming panel cancels editor safely");
 }
 Console.WriteLine("PASS independent actual HUD fixed/editor pointer "+checks+" assertions; actions/rendering/geometry setters are explicit stubs.");
 }
}
